icons=[ '<path d="M11 38C3 27 9 17 19 20C20 5 35 5 37 19C51 12 57 28 44 39L28 51Z"/><path d="M20 33l7 7 14-15"/>', '<path d="M8 29Q30 0 52 29Q30 58 8 29Z"/><circle cx="30" cy="29" r="8"/><path d="M30 2V9m0 42v7M2 29h6m44 0h6"/>', '<path d="M10 47V25L30 9l20 16v22H10Z"/><path d="M24 47V32h12v15M18 20V9h7"/><path d="M27 23h6"/>' ]
