cards=''.join(f'<article class="card"><span class="card-num">0{i+1} / {s}</span><svg viewBox="0 0 60 60" aria-hidden="true">{icons[i]}</svg><h3>{c[0]}</h3><p>{c[1]}<br>{c[2]}</p><button data-care="{i}" aria-label="了解{c[0]}">↗</button></article>' for i,(s,c) in enumerate(zip(['RITUAL','UNDERSTAND','BELONG'],cardcopy)))
body='''<a class="skip" href="#main">跳转到主要内容</a><div class="shell"><header><a class="brand" href="#" aria-label="MELLOW 尾伴 首页"><i></i>MELLOW<span>尾伴</span></a><nav aria-label="主导航"><a href="#companions">遇见伙伴</a><a href="#rituals">陪伴灵感</a><a href="#about">关于尾伴</a></nav><button class="outline" data-start>找到你的节奏 <span class="arrow">↗</span></button></header><main id="main"><section class="hero" id="companions" aria-label="宠物陪伴场景"><div class="hero-copy"><div class="eyebrow">A LITTLE WILD. A LOT OF LOVE.</div><h1>Life is better<br>with a little<br><em>wild.</em></h1><p class="lead">把日子过慢一点，把爱放大一点。<br>和毛茸茸的家人，一起找到生活的节奏。</p><div class="hero-actions"><button class="primary" data-start>开启陪伴提案 <span>↗</span></button><a class="text-link" href="#rituals">探索日常灵感</a></div><div class="small-note"><svg viewBox="0 0 40 28" aria-hidden="true"><path d="M3 15Q5 0 19 9Q32-2 36 13Q35 21 20 27Q5 23 3 15Z" fill="#d7eb77"/><path d="M10 16l6 5 14-12" fill="none" stroke="#392c40" stroke-width="1.5"/></svg>FOR THE ONES WHO MAKE A HOUSE A HOME.</div></div><div class="scene-wrap" tabindex="0" aria-roledescription="轮播" aria-label="伙伴场景；左右方向键切换，Home 到首张，End 到末张"><div class="scene"><div class="scene-bg"></div><div class="halo" data-depth="6"></div><div class="art" data-depth="14">__ART__</div><div class="mask"></div></div><div class="pill" data-depth="-8">THE GOOD LIFE CLUB</div><div class="stamp"><div>Made for<br>each other.<span>EST. 2026</span></div></div><div class="caption"><strong id="pet-name">Meet Milo.</strong><span id="pet-story">散步搭子 · 把普通日子变成探险</span></div><div class="slide-controls"><button class="circle" id="prev" aria-label="上一个伙伴">←</button><button class="circle" id="next" aria-label="下一个伙伴">→</button></div><div class="progress"><button class="dot" data-slide="0" aria-label="查看狗狗 Milo" aria-current="true"></button><button class="dot" data-slide="1" aria-label="查看猫咪 Miso" aria-current="false"></button><button class="dot" data-slide="2" aria-label="查看兔兔 Momo" aria-current="false"></button><span class="count">01 / 03</span></div><p class="live" id="slide-status" aria-live="polite" aria-atomic="true"></p></div></section><div class="ticker" aria-label="品牌理念"><span>Little rituals.</span><b>✳</b><span>Real connection.</span><b>✳</b><span>A softer kind of living.</span></div><section id="rituals" aria-labelledby="ritual-title"><div class="intro"><div><p class="section-label">01 — THE ART OF BEING TOGETHER</p><h2 id="ritual-title">爱，藏在日常的细节里。</h2></div><p>不必每一天都精彩。<br>有你在的小事，就是它的大世界。</p></div><div class="cards">__CARDS__</div></section><section class="manifesto" id="about" aria-labelledby="about-title"><div><p class="section-label">02 — YOUR KIND OF TOGETHER</p><h2 id="about-title">没有标准答案，<br>只有你们的<span style="color:var(--lime)">刚刚好。</span></h2><button class="primary" data-start>定制我的陪伴节奏 <span>↗</span></button></div><div class="right"><b>Less rush.<br>More us.</b><p>我们相信，好的陪伴从了解开始。<br>选择伙伴和日常节奏，<br>收下一份属于你们的小小灵感。</p></div></section></main><footer><div class="footer-brand">MELLOW<span>给每一种陪伴，留一点温柔。</span></div><p>© 2026 MELLOW · CONCEPT DESIGN</p><a class="text-link" href="#main">回到顶部 ↑</a></footer></div>
<dialog id="planner" aria-labelledby="planner-title"><button class="close" aria-label="关闭提案">×</button><p class="section-label">A LITTLE PLAN FOR YOU</p><h2 id="planner-title">你们的日常，是什么样？</h2><form id="plan-form"><fieldset><legend>01 / 和谁一起生活？</legend><div class="choices"><label><input type="radio" name="pet" value="dog" checked>狗狗</label><label><input type="radio" name="pet" value="cat">猫咪</label><label><input type="radio" name="pet" value="rabbit">兔兔</label></div></fieldset><fieldset><legend>02 / 今天想怎样相处？</legend><div class="choices"><label><input type="radio" name="mood" value="slow" checked>安静慢下来</label><label><input type="radio" name="mood" value="play">一起玩一会儿</label></div></fieldset><button class="primary" type="submit">生成陪伴提案 <span>↗</span></button></form><div id="plan-result" class="result" hidden tabindex="-1" role="status"></div><button id="try-again" class="outline" hidden style="margin-top:18px">重新选择</button><p class="modal-note">这是在本页即时生成的日常灵感，无需注册。</p></dialog>
<dialog id="care" aria-labelledby="care-title"><button class="close" aria-label="关闭灵感">×</button><p class="section-label">THE LITTLE THINGS</p><h2 id="care-title"></h2><p id="care-copy" style="font-size:14px;line-height:2"></p><button class="primary" id="care-start">找到我的节奏 ↗</button></dialog>'''.replace('__ART__',arts['dog']).replace('__CARDS__',cards)

js=r'''
const arts=__ARTS__;
const slides=[{name:'Meet Milo.',story:'散步搭子 · 把普通日子变成探险',color:'#efc4aa',kind:'dog'},{name:'Meet Miso.',story:'安静室友 · 陪你享受午后的留白',color:'#dcd8e8',kind:'cat'},{name:'Meet Momo.',story:'温柔邻居 · 分享一个慢慢的下午',color:'#dbe1bc',kind:'rabbit'}];
const scene=document.querySelector('.scene'),wrap=document.querySelector('.scene-wrap'),art=document.querySelector('.art'),mq=matchMedia('(prefers-reduced-motion: reduce)');let current=0,timer,origin=null;
function showSlide(n){current=(n+slides.length)%slides.length;const s=slides[current];clearTimeout(timer);scene.classList.remove('is-changing');art.innerHTML=arts[s.kind];document.querySelector('.scene-bg').style.background=s.color;scene.style.background=s.color;document.querySelector('#pet-name').textContent=s.name;document.querySelector('#pet-story').textContent=s.story;document.querySelector('.count').textContent=`0${current+1} / 03`;document.querySelectorAll('[data-slide]').forEach((b,i)=>b.setAttribute('aria-current',i===current?'true':'false'));document.querySelector('#slide-status').textContent=`第 ${current+1} 张，共 3 张。${s.name} ${s.story}`;if(!mq.matches){void scene.offsetWidth;scene.classList.add('is-changing');timer=setTimeout(()=>scene.classList.remove('is-changing'),700)}}
document.querySelector('#prev').onclick=()=>showSlide(current-1);document.querySelector('#next').onclick=()=>showSlide(current+1);document.querySelectorAll('[data-slide]').forEach(b=>b.onclick=()=>showSlide(+b.dataset.slide));wrap.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();showSlide(e.key==='Home'?0:e.key==='End'?2:current+(e.key==='ArrowRight'?1:-1))}});wrap.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')origin=e.clientX});wrap.addEventListener('pointerup',e=>{if(origin!==null&&Math.abs(e.clientX-origin)>45)showSlide(current+(e.clientX<origin?1:-1));origin=null});wrap.addEventListener('pointercancel',()=>origin=null);
let pointerX=0,pointerY=0,frame=0;const layers=[...document.querySelectorAll('[data-depth]')];function renderParallax(){frame=0;if(mq.matches)return;const rect=wrap.getBoundingClientRect();const scroll=Math.max(-1,Math.min(1,(innerHeight/2-rect.top-rect.height/2)/innerHeight));layers.forEach(el=>{let d=+el.dataset.depth;el.style.transform=`translate3d(${pointerX*d}px,${pointerY*d+scroll*d*.8}px,0)${el.classList.contains('pill')?' rotate(-8deg)':''}`})}function schedule(){if(!frame&&!mq.matches)frame=requestAnimationFrame(renderParallax)}wrap.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const r=wrap.getBoundingClientRect();pointerX=(e.clientX-r.left)/r.width-.5;pointerY=(e.clientY-r.top)/r.height-.5;schedule()});wrap.addEventListener('pointerleave',()=>{pointerX=0;pointerY=0;schedule()});addEventListener('scroll',schedule,{passive:true});mq.addEventListener('change',()=>{clearTimeout(timer);scene.classList.remove('is-changing');layers.forEach(el=>el.style.transform='');if(mq.matches){cancelAnimationFrame(frame);frame=0}else schedule()});
const planner=document.querySelector('#planner'),care=document.querySelector('#care'),form=document.querySelector('#plan-form'),result=document.querySelector('#plan-result'),again=document.querySelector('#try-again');const returnFocus=new WeakMap();
function openDialog(dialog){returnFocus.set(dialog,document.activeElement);dialog.showModal()}function resetPlan(){form.hidden=false;result.hidden=true;again.hidden=true}function start(){resetPlan();form.elements.pet.value=slides[current].kind;openDialog(planner)}document.querySelectorAll('[data-start]').forEach(b=>b.onclick=start);document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const candidates=[...d.querySelectorAll('button,input,a[href],[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length&&(el.type!=='radio'||el.checked));const first=candidates[0],last=candidates[candidates.length-1];if(e.shiftKey&&(document.activeElement===first||!d.contains(document.activeElement))){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||!d.contains(document.activeElement))){e.preventDefault();first.focus()}});d.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))returnFocus.get(d)?.focus()})});
const ideas={dog:{slow:'把手机放下，陪它在熟悉的角落坐一会儿。让它自己决定靠近的距离，把安静也留在今天的回忆里。',play:'拿起它熟悉的玩具，来一次短短的互动。留意它的兴致，兴致散了就一起休息。'},cat:{slow:'在它喜欢的窗边留一个舒服的位置。你读几页书，它看看外面的世界，不打扰也是一种陪伴。',play:'用它喜欢的玩具邀请一次小追逐，让它有机会追到目标；它转身离开时，就让这场游戏结束。'},rabbit:{slow:'坐在它熟悉的空间附近，让它主动探索你。动作放慢，不追逐、不强抱，给温柔一点时间。',play:'在安全的活动空间摆一个纸隧道，让它自己决定是否探索。陪它观察今天的新发现。'}};
form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);result.textContent=ideas[data.get('pet')][data.get('mood')];form.hidden=true;result.hidden=false;again.hidden=false;result.focus()});again.onclick=()=>{resetPlan();form.querySelector('input').focus()};
const careTitles=__TITLES__,careTexts=['给每天留一个可预期的小片刻：一次问候、一段共同休息的时间。仪式不需要复杂，稳定而温柔的回应就很好。','先观察，再回应。它主动靠近时给予关注，它转身离开时留出空间。慢慢了解每个小动作背后的偏好。','把休息区放在安静、舒适的位置，减少打扰。当它选择独处，就让陪伴以守候的方式发生。'];document.querySelectorAll('[data-care]').forEach(b=>b.onclick=()=>{const i=+b.dataset.care;document.querySelector('#care-title').textContent=careTitles[i];document.querySelector('#care-copy').textContent=careTexts[i];openDialog(care)});document.querySelector('#care-start').onclick=()=>{care.close();start()};
'''.replace('__ARTS__',json.dumps(arts,ensure_ascii=False)).replace('__TITLES__',json.dumps([c[0] for c in cardcopy],ensure_ascii=False))

