# Vector design boards: keep text as live <text>, geometry as native SVG.
def text(x,y,s,size=14,fill=INK,family='Arial, Microsoft YaHei, sans-serif',extra=''):
    return f'<text x="{x}" y="{y}" fill="{fill}" font-family="{family}" font-size="{size}" {extra}>{html.escape(s)}</text>'
def rect(x,y,w,h,fill,rx=0,stroke='none'):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" fill="{fill}" stroke="{stroke}"/>'
def line(x,y,x2,y2,col='#D9D4CC'):
    return f'<path d="M{x} {y}H{x2}" stroke="{col}"/>' if y==y2 else f'<path d="M{x} {y}L{x2} {y2}" stroke="{col}"/>'
def btn(x,y,w,label,fill=INK,fg=CREAM):
    return rect(x,y,w,54,fill,27)+text(x+24,y+33,label,13,fg)+text(x+w-37,y+34,'↗',20,fg)
def art_inner(kind): return arts[kind].split('>',1)[1].rsplit('</svg>',1)[0]

